# smn-playground parity tooling. Run from the repository root via playground/tools/parity.sh.
"""Emit the exact bench MJCF used by smn-playground (generated by smn-lab's own builders)."""
import json, sys, subprocess
sys.path.insert(0, sys.argv[1])
from smn_lab.crawler import build_crawler_xml
from smn_lab.medusa import medusa_spec
from smn_lab.lattice import _lattice_mjcf
sha = subprocess.check_output(["git", "-C", sys.argv[1], "rev-parse", "--short", "HEAD"]).decode().strip()
out = {"smn_lab_commit": sha, "crawler": {}, "medusa": {}}
for n in range(3, 13):
    out["crawler"][f"aquarium_{n}"] = build_crawler_xml(n_seg=n)                      # C0 settings
    out["crawler"][f"terrarium_{n}"] = build_crawler_xml(n_seg=n, gravity_on=False,    # gravity_locomotion settings
                                         joint_damping=0.03, bend_limit_deg=50.0)
# medusa_swim.py: medusa_spec(z_apex=0.30); build_medusa(cmax=13, seg_damp=1.3, lat_stiff=20); dt=0.001
for nt in (0, 6):
    sp = medusa_spec(z_apex=0.30, n_tent=nt) if nt else medusa_spec(z_apex=0.30, n_tent=1, l_tent=0)
    xml = _lattice_mjcf(sp["pos"], sp["edges"], lat_stiff=20.0, link_damp=0.5, seg_damp=1.3,
                        seg_mass=0.05, cmax=13.0, name="medusa")
    xml = xml.replace('timestep="0.002"', 'timestep="0.001"')
    out["medusa"][f"tent_{nt}"] = dict(xml=xml, edges=[list(map(int, e)) for e in sp["edges"]],
        edge_kind=sp["edge_kind"].tolist(), coronal=sp["coronal"], pos=sp["pos"].tolist())
json.dump(out, open(sys.argv[2], "w"))
print("ok", sha, {k: len(v) for k, v in out.items() if isinstance(v, dict)})
